template.script:
(function() {
    function cleanChrome() {
        var selectors = [
            'header#top',
            'header.o_header_standard',
            'nav.navbar',
            'footer#bottom',
            'footer.o_footer',
            '.o_portal_submenu',
            '.breadcrumb',
            '.o_portal_my_doc_breadcrumbs',
            '#oe_neutralize_banner'
        ];
        selectors.forEach(function(sel) {
            document.querySelectorAll(sel).forEach(function(el) {
                el.style.display = 'none';
                el.remove();
            });
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', cleanChrome);
    } else {
        cleanChrome();
    }
    setTimeout(cleanChrome, 50);
    setTimeout(cleanChrome, 300);
})();

t.script:
function stepQty(lineId, delta) {
    var input = document.getElementById('qty_' + lineId);
    if (!input) return;
    input.value = Math.max(0, (parseFloat(input.value) || 0) + delta);
    recalcLine(lineId);
}
function recalcLine(lineId) {
    var input = document.getElementById('qty_' + lineId);
    var row = document.getElementById('row_' + lineId);
    if (!input || !row) return;
    var price = parseFloat(row.getAttribute('data-price')) || 0;
    var disc = parseFloat(row.getAttribute('data-disc')) || 0;
    var tax = parseFloat(row.getAttribute('data-tax')) || 0;
    var qty = Math.max(0, parseFloat(input.value) || 0);
    if (qty !== (parseFloat(input.value) || 0)) input.value = qty;
    var untaxed = qty * price * (1 - disc / 100);
    row.setAttribute('data-untaxed', untaxed);
    row.setAttribute('data-taxamt', untaxed * tax / 100);
    row.setAttribute('data-worth', disc >= 100 ? qty * price : 0);
    var cell = document.getElementById('subtotal_' + lineId);
    if (cell) cell.innerText = untaxed.toFixed(2);
    recalcTotals();
}
function recalcTotals() {
    var units = 0, untaxed = 0, tax = 0, free = 0;
    document.querySelectorAll('tr.dp-line').forEach(function(row) {
        var id = row.id.replace('row_', '');
        var input = document.getElementById('qty_' + id);
        var qty = input ? (parseFloat(input.value) || 0) : (parseFloat(row.getAttribute('data-qty')) || 0);
        var price = parseFloat(row.getAttribute('data-price')) || 0;
        var disc = parseFloat(row.getAttribute('data-disc')) || 0;
        var rate = parseFloat(row.getAttribute('data-tax')) || 0;
        var base = qty * price * (1 - disc / 100);
        units += qty;
        untaxed += base;
        tax += base * rate / 100;
        if (disc >= 100) free += qty * price;
    });
    var set = function(id, v) { var el = document.getElementById(id); if (el) el.innerText = v; };
    set('grand_total_units', units);
    set('grand_untaxed', untaxed.toFixed(2));
    set('grand_tax', tax.toFixed(2));
    set('grand_free', free.toFixed(2));
    set('grand_total_amount', (untaxed + tax).toFixed(2));
}
function openCustomModal(id) {
    var b = document.getElementById('custom_modal_backdrop'), m = document.getElementById(id);
    if (b && m) { b.classList.add('active'); m.classList.add('active'); }
}
function closeCustomModal(id) {
    var b = document.getElementById('custom_modal_backdrop'), m = document.getElementById(id);
    if (m) m.classList.remove('active');
    if (b) b.classList.remove('active');
}
function closeAllCustomModals() {
    document.querySelectorAll('.custom-modal').forEach(function(m) { m.classList.remove('active'); });
    var b = document.getElementById('custom_modal_backdrop');
    if (b) b.classList.remove('active');
}
function showRejectModal() {
    var notes = document.getElementById('order_notes') ? document.getElementById('order_notes').value.trim() : '';
    var input = document.getElementById('modal_reject_reason');
    if (input && notes) input.value = notes;
    openCustomModal('custom_reject_modal');
}
function executeRejection() {
    var input = document.getElementById('modal_reject_reason');
    var notes = document.getElementById('order_notes');
    if (input && notes && input.value.trim()) notes.value = input.value.trim();
    var form = document.getElementById('distributor_order_form');
    form.action = form.getAttribute('data-base') + '/reject';
    form.submit();
}
function showConfirmModal() {
    var units = 0;
    document.querySelectorAll('.qty-input').forEach(function(i) { units += parseFloat(i.value) || 0; });
    if (units <= 0) { openCustomModal('custom_alert_modal'); return; }
    var u = document.getElementById('grand_total_units'), a = document.getElementById('grand_total_amount');
    var cu = document.getElementById('modal_confirm_units'), ca = document.getElementById('modal_confirm_amount');
    if (cu) cu.innerText = u ? u.innerText : units;
    if (ca) ca.innerText = a ? a.innerText : '0.00';
    openCustomModal('custom_confirm_modal');
}
function executeConfirmation() {
    var form = document.getElementById('distributor_order_form');
    form.action = form.getAttribute('data-base') + '/submit';
    form.submit();
}
document.addEventListener('DOMContentLoaded', function() { recalcTotals(); });
